    static func translate(_ plugin:String?,_ key:String,_ params:NativePluginRecord?,_ locale:String)->String {
        let id=plugin ?? "core",locales=messages[id] as? NativePluginRecord ?? [:]
        var node:Any = locales[locale] ?? locales["en"] ?? NativePluginRecord()
        for part in key.components(separatedBy:".") { guard let value=(node as? NativePluginRecord)?[part] else { return id+":"+key };node=value }
        guard var text=node as? String else { return id+":"+key }
        let pattern=try! NSRegularExpression(pattern:#"\{([A-Za-z0-9_]+)\}"#)
        for match in pattern.matches(in:text,range:NSRange(text.startIndex...,in:text)).reversed() {
            guard let nameRange=Range(match.range(at:1),in:text),let range=Range(match.range,in:text),let value=params?[String(text[nameRange])] else { return id+":"+key }
            text.replaceSubrange(range,with:NativePluginJSON.string(value))
        }
        return text
    }
